package org.apache.commons.lang3.text;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertSame;

import org.apache.commons.lang3.AbstractLangTest;
import org.junit.jupiter.api.Test;

/**
 * Tests {@link StrMatcher#doubleQuoteMatcher()}.
 */
@Deprecated
public class StrMatcherTest_testDoubleQuoteMatcher extends AbstractLangTest {

    /**
     * A mixed buffer whose last two characters are a single quote (index 11)
     * followed by a double quote (index 12). This lets us check that the
     * double-quote matcher rejects the single quote but accepts the double quote.
     * The leading characters are an assortment of separators (comma, tab,
     * newline, NUL, etc.) that are irrelevant to the two positions under test.
     */
    private static final char[] BUFFER = "0,1\t2 3\n\r\f�'\"".toCharArray();

    /** Index of the single quote (') in {@link #BUFFER}. */
    private static final int SINGLE_QUOTE_INDEX = 11;

    /** Index of the double quote (") in {@link #BUFFER}. */
    private static final int DOUBLE_QUOTE_INDEX = 12;

    @Test
    void testDoubleQuoteMatcher() {
        final StrMatcher matcher = StrMatcher.doubleQuoteMatcher();

        // The factory always returns the same shared instance.
        assertSame(matcher, StrMatcher.doubleQuoteMatcher());

        // A single quote is not a double quote: no characters match.
        assertEquals(0, matcher.isMatch(BUFFER, SINGLE_QUOTE_INDEX));

        // A double quote matches exactly one character.
        assertEquals(1, matcher.isMatch(BUFFER, DOUBLE_QUOTE_INDEX));
    }
}
